style.css:
@-moz-document domain("roblox.com") {
/* 1. Устанавливаем ваше фото на фон */
    html {
        background: url("https://i.yapx.ru/eXrrM.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. Делаем фон основных контейнеров прозрачным, чтобы фото было видно */
    body, #app, .content, .container, .main-container, .page-content,
    .game-card, .section, .rbx-body, .rbx-page-content,
    .rbx-navbar, .rbx-header, .rbx-footer, .rbx-banner,
    .rbx-left-col, .rbx-right-col {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 3. Убираем встроенные цвета/фоны, которые могут перекрывать фото */
    [style*="background-image"] {
        background-image: none !important;
    }
    [style*="background-color"] {
        background-color: transparent !important;
    }

    /* 4. Легкая затемняющая подложка для текста, чтобы он не сливался со светлым фото */
    .text-overflow, .text-label, .game-name, .section-content, 
    .rbx-navbar, .rbx-header, .rbx-footer {
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important; 
    }
    
    /* Делаем карточки игр и меню чуть темнее для читаемости */
    .game-card, .section, .rbx-navbar, .rbx-footer {
        background-color: rgba(0, 0, 0, 0.2) !important; 
        backdrop-filter: blur(3px) !important; 
        border-radius: 8px !important;
    }
}
